/// The number spec for `lang` in numbering system `ns`. CLDR only ships
/// symbols for a handful of systems per locale; anything else resolves to
/// the locale's `latn` block, which is ICU's `NumberElements` fallback.
pub(crate) fn spec(lang: &str, ns: &str) -> Option<NumberSpec> {
    let i = locale_index(lang)?;
    if let Some(s) = other(i, ns) {
        return Some(s);
    }
    latn(i)
}

